import{_ as i,l,o as a,c as n,v as o,p as s,x as r,d,i as c,S as p}from"./chunks/framework.InCnrqk-.js";const T=JSON.parse('{"title":"链接器符号解析与归档","description":"","frontmatter":{"title":"链接器符号解析与归档","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/linker-symbol-resolution.md","filePath":"cs/linker-symbol-resolution.md","lastUpdated":1789023840000}'),h={name:"cs/linker-symbol-resolution.md"};function m(_,e,E,u,A,f){const t=l("Mermaid");return a(),n("div",null,[e[1]||(e[1]=o('<h1 id="链接器符号解析与归档" tabindex="-1">链接器符号解析与归档 <a class="header-anchor" href="#链接器符号解析与归档" aria-label="Permalink to &quot;链接器符号解析与归档&quot;">​</a></h1><div class="epigraph"><p>未定义引用在输入 `.o` 与归档成员中查找定义。静态库是按需抽取的目标文件包：只有被引用的成员才拉进来。</p><footer>—— 据 System V ABI；Levine, Linkers and Loaders；龙书第 7 章；主干[链接与重定位](/cs/link-reloc) 整理</footer></div><p>上一课<a href="/cs/name-mangling">符号与 mangling</a> 给出扁平名字。主干链接课已有重定位直觉。缺口是<strong>解析算法与 <code>.a</code> 归档</strong>：扫描次序、弱符号、重复定义。本课钉静态解析，动态下一课之后。链接课序从这里开始。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>链接器维护已定义集合与未定义集合。读入 <code>.o</code>：定义满足未定义，新未定义加入。归档：只当当前未定义命中某成员才抽取该成员，可能再引入新未定义，循环直到稳。缺口是<strong>这份工作表</strong>，不是 mangling 规则。</p><p>次序：传统 Unix 从左到右，<code>--start-group</code> 解循环依赖。重复强符号报错；弱被强覆盖。</p><h3 id="归档不是「把目录打成-zip-就执行」" tabindex="-1">归档不是「把目录打成 zip 就执行」 <a class="header-anchor" href="#归档不是「把目录打成-zip-就执行」" aria-label="Permalink to &quot;归档不是「把目录打成 zip 就执行」&quot;">​</a></h3><p><code>.a</code> 不是可执行。成员是 <code>.o</code>。ranlib 符号表加速查找。不要和 <code>.so</code> 混。</p><p><span class="marginnote">Levine 的 Linkers and Loaders。GNU ld。主干 link-reloc 课。本课补归档与解析策略。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>命令行顺序读入。对每个符号：绑定 GLOBAL/WEAK/LOCAL。LTO 位码对象当 IR 包，解析后进优化——<a href="/cs/lto">LTO</a>。</p>',11)),(a(),s(p,null,{default:r(()=>[c(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20UND%5B%22%E6%9C%AA%E5%AE%9A%E4%B9%89%22%5D%20--%3E%20OBJ%5B%22.o%20%E5%AE%9A%E4%B9%89%22%5D%0A%20%20UND%20--%3E%20AR%5B%22.a%20%E6%8C%89%E9%9C%80%E6%88%90%E5%91%98%22%5D%0A%20%20OBJ%20--%3E%20REL%5B%22%E5%BE%85%E9%87%8D%E5%AE%9A%E4%BD%8D%22%5D%0A%20%20AR%20--%3E%20REL%0A"})]),fallback:r(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>与可见性：<code>hidden</code> 不进动态符号表，但仍参与静态解析。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>循环依赖库要用组或合并 <code>.o</code>。不要靠运气次序。C++ 静态构造的拉入：归档可能丢掉只含构造函数的成员，需 <code>--whole-archive</code> 或显式引用。</p><p>弱符号服务内联与模板的 COMDAT，下一课 ICF 再折同码。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写动态 <code>DT_NEEDED</code>。后课默认：静态解析按序+归档抽取。下一课链接脚本与段。</p><p>也不把解析当 DNS。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>解析：未定义到定义；归档按需抽成员。</li><li>强弱、次序、循环组是工程规则。</li><li>与 LTO 对象同一符号模型。</li><li>出处：Levine；System V ABI；Aho et al. 龙书。</li></ul>',9))])}const k=i(h,[["render",m]]);export{T as __pageData,k as default};
